// Packages: AWSSDK.S3, Amazon.S3
using Amazon.S3;
using Amazon.S3.Model;

public class S3StorageService
{
    private readonly IAmazonS3 _s3Client;
    private const string BucketName = "aspnet-aws-demo-bucket";

    public S3StorageService(IAmazonS3 s3Client)
    {
        _s3Client = s3Client ?? throw new ArgumentNullException(nameof(s3Client));
    }

    public async Task UploadFileAsync(string filePath, string key, CancellationToken cancellationToken = default)
    {
        try
        {
            var putRequest = new PutObjectRequest
            {
                BucketName = BucketName,
                Key = key,
                FilePath = filePath
            };

            PutObjectResponse response = await _s3Client.PutObjectAsync(putRequest, cancellationToken);
            Console.WriteLine($"Uploaded {filePath} to s3://{BucketName}/{key} (ETag: {response.ETag})");
        }
        catch (AmazonS3Exception ex)
        {
            Console.WriteLine($"S3 upload error: {ex.Message}");
            throw;
        }
    }

    public async Task DownloadFileAsync(string key, string destinationPath, CancellationToken cancellationToken = default)
    {
        try
        {
            var getRequest = new GetObjectRequest
            {
                BucketName = BucketName,
                Key = key
            };

            using var response = await _s3Client.GetObjectAsync(getRequest, cancellationToken);
            await using var fileStream = File.OpenWrite(destinationPath);
            await response.ResponseStream.CopyToAsync(fileStream, cancellationToken);
            Console.WriteLine($"Downloaded s3://{BucketName}/{key} to {destinationPath}");
        }
        catch (AmazonS3Exception ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            Console.WriteLine($"Object not found: s3://{BucketName}/{key}");
            throw new FileNotFoundException("S3 object not found", key, ex);
        }
    }
}

