// Packages: AWSSDK.S3, Amazon.S3
using Amazon.S3;
using Amazon.S3.Model;

public class S3ManagementService
{
    private readonly IAmazonS3 _s3Client;
    private const string BucketName = "aspnet-aws-demo-bucket";

    public S3ManagementService(IAmazonS3 s3Client)
    {
        _s3Client = s3Client;
    }

    public async Task ListObjectsAsync(CancellationToken cancellationToken = default)
    {
        try
        {
            var listRequest = new ListObjectsV2Request
            {
                BucketName = BucketName
            };

            ListObjectsV2Response listResponse;
            do
            {
                listResponse = await _s3Client.ListObjectsV2Async(listRequest, cancellationToken);
                foreach (var obj in listResponse.S3Objects)
                {
                    Console.WriteLine($"{obj.Key} - {obj.Size} bytes (LastModified: {obj.LastModified:yyyy-MM-dd})");
                }
                listRequest.ContinuationToken = listResponse.NextContinuationToken;
            } while (listResponse.IsTruncated);
        }
        catch (AmazonS3Exception ex)
        {
            Console.WriteLine($"S3 list error: {ex.Message}");
            throw;
        }
    }

    public async Task DeleteObjectAsync(string key, CancellationToken cancellationToken = default)
    {
        try
        {
            var deleteRequest = new DeleteObjectRequest
            {
                BucketName = BucketName,
                Key = key
            };

            DeleteObjectResponse response = await _s3Client.DeleteObjectAsync(deleteRequest, cancellationToken);
            Console.WriteLine($"Deleted s3://{BucketName}/{key} (RequestId: {response.ResponseMetadata.RequestId})");
        }
        catch (AmazonS3Exception ex)
        {
            Console.WriteLine($"S3 delete error: {ex.Message}");
            throw;
        }
    }
}

