// Packages: AWSSDK.S3, Amazon.S3
using Amazon.S3;
using Amazon.S3.Model;

public static string GeneratePresignedDownloadUrl(string key, TimeSpan? expiresIn = null)
{
    try
    {
        var s3Client = new AmazonS3Client(RegionEndpoint.USEast1);

        var request = new GetPreSignedUrlRequest
        {
            BucketName = "aspnet-aws-demo-bucket",
            Key = key,
            Verb = HttpVerb.GET,
            Expires = DateTime.UtcNow.Add(expiresIn ?? TimeSpan.FromHours(1))
        };

        string url = s3Client.GetPreSignedURL(request);
        Console.WriteLine($"Presigned URL generated: {url}");
        return url;
    }
    catch (AmazonS3Exception ex)
    {
        Console.WriteLine($"Error generating presigned URL: {ex.Message}");
        throw;
    }
}

